using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A shortest-path search in each language that adds an edge's length to the length kept for the place the edge goes to, not
/// the place it comes from, with the change that starts from the place it comes from; the same searches starting there, and
/// programs near the mistake but not it, which are left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class PathFromWrongEndTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

