    [Theory]
    [MemberData(nameof(Searches))]
    public void ALengthWorkedOutFromTheEndTheEdgeGoesToIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The searches starting from the place the edge comes from; one working the length through the place out first; one
    /// asking the other way round whether the kept length is longer; Bellman-Ford's relaxation; a sum tested for going past what
    /// an unsigned number holds; and the smaller of a value and the value with a change, with no graph in sight.
    /// </summary>
    [Theory]
    [InlineData("dijkstra.c", "#include <stdio.h>\n\n#define N 4\n#define INF 1000000000\n\nint main(void) {\n    int graph[N][N] = {{0, 4, 1, 0}, {0, 0, 0, 1}, {0, 2, 0, 5}, {0, 0, 0, 0}};\n    int dist[N] = {0, INF, INF, INF};\n    int done[N] = {0};\n    for (int round = 0; round < N; round++) {\n        int node = -1;\n        for (int i = 0; i < N; i++) {\n            if (!done[i] && (node < 0 || dist[i] < dist[node])) node = i;\n        }\n        done[node] = 1;\n        for (int next = 0; next < N; next++) {\n            if (graph[node][next] > 0 && dist[node] + graph[node][next] < dist[next]) dist[next] = dist[node] + graph[node][next];\n        }\n    }\n    for (int i = 0; i < N; i++) printf(i > 0 ? \" %d\" : \"%d\", dist[i]);\n    printf(\"\\n\");\n    return 0;\n}\n")]
    [InlineData("dijkstra.cpp", "#include <iostream>\n#include <queue>\n#include <utility>\n#include <vector>\n\nint main() {\n    const int inf = 1000000000;\n    std::vector<std::vector<std::pair<int, int>>> graph = {{{1, 4}, {2, 1}}, {{3, 1}}, {{1, 2}, {3, 5}}, {}};\n    std::vector<int> dist = {0, inf, inf, inf};\n    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> queue;\n    queue.push({0, 0});\n    while (!queue.empty()) {\n        auto [distance, node] = queue.top();\n        queue.pop();\n        for (auto [next, length] : graph[node]) {\n            int shorter = std::min(dist[next], dist[node] + length);\n            if (shorter < dist[next]) {\n                dist[next] = shorter;\n                queue.push({shorter, next});\n            }\n        }\n    }\n    for (std::size_t i = 0; i < dist.size(); i++) std::cout << (i > 0 ? \" \" : \"\") << dist[i];\n    std::cout << std::endl;\n    return 0;\n}\n")]
    [InlineData("dijkstra.dart", "void main() {\n  const inf = 1000000000;\n  final graph = [\n    [[1, 4], [2, 1]],\n    [[3, 1]],\n    [[1, 2], [3, 5]],\n    <List<int>>[],\n  ];\n  final dist = [0, inf, inf, inf];\n  final done = [false, false, false, false];\n  for (var round = 0; round < 4; round++) {\n    var node = -1;\n    for (var i = 0; i < 4; i++) {\n      if (!done[i] && (node < 0 || dist[i] < dist[node])) node = i;\n    }\n    done[node] = true;\n    for (final edge in graph[node]) {\n      final next = edge[0];\n      final length = edge[1];\n      if (dist[node] + length < dist[next]) {\n        dist[next] = dist[node] + length;\n      }\n    }\n  }\n  print(dist.join(' '));\n}\n")]
    [InlineData("dijkstra.f90", "program shortest\n  implicit none\n  integer, parameter :: n = 4, inf = 1000000000\n  integer :: graph(n, n), dist(n), node, nxt, round, i\n  logical :: done(n)\n  graph = 0\n  graph(1, 2) = 4\n  graph(1, 3) = 1\n  graph(2, 4) = 1\n  graph(3, 2) = 2\n  graph(3, 4) = 5\n  dist = inf\n  dist(1) = 0\n  done = .false.\n  do round = 1, n\n    node = 0\n    do i = 1, n\n      if (.not. done(i) .and. (node == 0)) node = i\n      if (.not. done(i) .and. node > 0) then\n        if (dist(i) < dist(node)) node = i\n      end if\n    end do\n    done(node) = .true.\n    do nxt = 1, n\n      if (graph(node, nxt) > 0 .and. dist(node) + graph(node, nxt) < dist(nxt)) dist(nxt) = dist(node) + graph(node, nxt)\n    end do\n  end do\n  print '(I0, 3(1X, I0))', dist\nend program shortest\n")]
