    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\n\npublic static class Program\n{\n    const int Inf = 1000000000;\n\n    public static void Main()\n    {\n        var graph = new List<(int Next, int Length)>[]\n        {\n            new() { (1, 4), (2, 1) },\n            new() { (3, 1) },\n            new() { (1, 2), (3, 5) },\n            new(),\n        };\n        var dist = new[] { 0, Inf, Inf, Inf };\n        var queue = new PriorityQueue<int, int>();\n        queue.Enqueue(0, 0);\n        while (queue.TryDequeue(out int node, out int _))\n        {\n            foreach (var (next, length) in graph[node])\n            {\n                int shorter = Math.Min(dist[next], dist[node] + length);\n                if (shorter < dist[next])\n                {\n                    dist[next] = shorter;\n                    queue.Enqueue(next, shorter);\n                }\n            }\n        }\n\n        Console.WriteLine(string.Join(\" \", dist));\n    }\n}\n")]
    [InlineData("relax.py", "import heapq\n\ngraph = {0: [(1, 4), (2, 1)], 1: [(3, 1)], 2: [(1, 2), (3, 5)], 3: []}\n\n\ndef shortest(start):\n    dist = {node: float(\"inf\") for node in graph}\n    dist[start] = 0\n    heap = [(0, start)]\n    while heap:\n        distance, node = heapq.heappop(heap)\n        if distance > dist[node]:\n            continue\n        for next_node, length in graph[node]:\n            dist[next_node] = min(dist[next_node], dist[node] + length)\n            heapq.heappush(heap, (dist[next_node], next_node))\n    return dist\n\n\nlengths = shortest(0)\nprint(*(lengths[node] for node in sorted(lengths)))\n")]
